head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .navigation {
  display: none;
}
body#layout .page {
  display: inline-block;
  vertical-align: top;
  width: 55%;
}
body#layout .sidebar-container {
  display: inline-block;
  float: right;
  width: 40%;
}
body#layout .hamburger-menu,
body#layout .search {
  display: none;
}

b:includable.script:
function googleTranslateElementInit() {
  new google.translate.TranslateElement({
    pageLanguage: '',
    autoDisplay: 'true',
    layout: google.translate.TranslateElement.InlineLayout.
  }, 'google_translate_element');
}

body.script:
/* ShiftMate Blogger language/menu runtime v6 — 10 locales, Page-based FAQ/Guide. */
(function () {
  'use strict';

  var LOCALES = {
    en: {name:'English', tag:'en', path:['lang','lang-en','English'], blog:'/search/label/lang', legacyBlog:'/search/label/lang-en', faq:'/p/faq.html', notice:'/search/label/lang+notice', guide:'/p/guide.html', story:'/search/label/lang+story', legacyStory:'/search/label/lang-en+story'},
    es: {name:'Español', tag:'es', path:['lang-es','español','Español'], blog:'/search/label/lang-es', faq:'/p/faq-es.html', notice:'/search/label/lang-es+notice', guide:'/p/guide-es.html', story:'/search/label/lang-es+story'},
    de: {name:'Deutsch', tag:'de', path:['lang-de','Deutsch'], blog:'/search/label/lang-de', faq:'/p/faq-de.html', notice:'/search/label/lang-de+notice', guide:'/p/guide-de.html', story:'/search/label/lang-de+story'},
    fr: {name:'Français', tag:'fr', path:['lang-fr','Français','Francais'], blog:'/search/label/lang-fr', faq:'/p/faq-fr.html', notice:'/search/label/lang-fr+notice', guide:'/p/guide-fr.html', story:'/search/label/lang-fr+story'},
    'pt-BR': {name:'Português (Brasil)', tag:'pt-BR', path:['lang-pt-br','Português (Brasil)','Português','Portugues'], blog:'/search/label/lang-pt-br', faq:'/p/faq-pt-br.html', notice:'/search/label/lang-pt-br+notice', guide:'/p/guide-pt-br.html', story:'/search/label/lang-pt-br+story'},
    'zh-CN': {name:'简体中文', tag:'zh-CN', path:['lang-zh-cn','lang-zh-hans','简体中文','中文'], blog:'/search/label/lang-zh-cn', faq:'/p/faq-cn.html', notice:'/search/label/lang-zh-cn+notice', guide:'/p/guide-cn.html', story:'/search/label/lang-zh-cn+story'},
    'zh-TW': {name:'繁體中文', tag:'zh-TW', path:['lang-zh-tw','lang-zh-hant','繁體中文'], blog:'/search/label/lang-zh-tw', faq:'/p/faq-tw.html', notice:'/search/label/lang-zh-tw+notice', guide:'/p/guide-tw.html', story:'/search/label/lang-zh-tw+story'},
    ko: {name:'한국어', tag:'ko', path:['lang-ko','한국어'], blog:'/search/label/lang-ko', faq:'/p/faq-ko.html', notice:'/search/label/lang-ko+notice', guide:'/p/guide-ko.html', story:'/search/label/lang-ko+story'},
    ja: {name:'日本語', tag:'ja', path:['lang-ja','日本語'], blog:'/search/label/lang-ja', faq:'/p/faq-ja.html', notice:'/search/label/lang-ja+notice', guide:'/p/guide-ja.html', story:'/search/label/lang-ja+story'},
    vi: {name:'Tiếng Việt', tag:'vi', path:['lang-vi','Tiếng Việt'], blog:'/search/label/lang-vi', faq:'/p/faq-vi.html', notice:'/search/label/lang-vi+notice', guide:'/p/guide-vi.html', story:'/search/label/lang-vi+story'}
  };

  var ORDER = ['en','es','de','fr','pt-BR','zh-CN','zh-TW','ko','ja','vi'];

  var TEXT = {
    en: {desc:'News, guides and stories for your shift-working life.', help:'Explore ShiftMate', tag:'Your shifts. Your rhythm.', notice:'Notices', noticeDesc:'Check important updates and announcements.', guide:'User guide', guideDesc:'Learn how to use ShiftMate.', faq:'FAQ', faqDesc:'Find answers and troubleshooting tips.', story:'Stories', storyDesc:'Read posts in this language.', soon:'Coming soon', all:'Show all', filter:'Posts in English', search:'Search', searchHint:'Search this blog', read:'Read more', updateBadge:'Update'},
    es: {desc:'Noticias, guías e historias para tu vida por turnos.', help:'Explora ShiftMate', tag:'Tus turnos. Tu ritmo.', notice:'Avisos', noticeDesc:'Consulta novedades y anuncios importantes.', guide:'Guía de uso', guideDesc:'Aprende a usar ShiftMate.', faq:'Preguntas frecuentes', faqDesc:'Encuentra respuestas y soluciones.', story:'Historias', storyDesc:'Lee artículos en este idioma.', soon:'Próximamente', all:'Ver todo', filter:'Artículos en español', search:'Buscar', searchHint:'Buscar en el blog', read:'Leer más', updateBadge:'Actualización'},
    de: {desc:'Neuigkeiten, Anleitungen und Geschichten rund um Schichtarbeit mit ShiftMate.', help:'ShiftMate entdecken', tag:'Deine Schichten. Dein Rhythmus.', notice:'Mitteilungen', noticeDesc:'Wichtige Updates und Mitteilungen ansehen.', guide:'Benutzerhandbuch', guideDesc:'Erfahren Sie, wie Sie ShiftMate verwenden.', faq:'FAQ', faqDesc:'Antworten und Tipps zur Problemlösung finden.', story:'Geschichten', storyDesc:'Beiträge auf Deutsch lesen.', soon:'Demnächst', all:'Alle anzeigen', filter:'Beiträge auf Deutsch', search:'Suchen', searchHint:'Blog durchsuchen', read:'Weiterlesen', updateBadge:'Update'},
    fr: {desc:'Actualités, guides et récits sur le travail posté avec ShiftMate.', help:'Découvrir ShiftMate', tag:'Vos services. Votre rythme.', notice:'Annonces', noticeDesc:'Consultez les mises à jour et annonces importantes.', guide:'Guide d’utilisation', guideDesc:'Découvrez comment utiliser ShiftMate.', faq:'Questions fréquentes', faqDesc:'Trouvez des réponses et des conseils de dépannage.', story:'Récits', storyDesc:'Lisez les articles en français.', soon:'Bientôt disponible', all:'Tout afficher', filter:'Articles en français', search:'Rechercher', searchHint:'Rechercher dans le blog', read:'Lire la suite', updateBadge:'Mise à jour'},
    'pt-BR': {desc:'Notícias, guias e histórias sobre a vida em turnos com o ShiftMate.', help:'Conheça o ShiftMate', tag:'Seus turnos. Seu ritmo.', notice:'Avisos', noticeDesc:'Confira atualizações e comunicados importantes.', guide:'Guia de uso', guideDesc:'Aprenda a usar o ShiftMate.', faq:'Perguntas frequentes', faqDesc:'Encontre respostas e dicas para resolver problemas.', story:'Histórias', storyDesc:'Leia publicações em português.', soon:'Em breve', all:'Ver tudo', filter:'Publicações em português (Brasil)', search:'Pesquisar', searchHint:'Pesquisar no blog', read:'Leia mais', updateBadge:'Atualização'},
    'zh-CN': {desc:'ShiftMate 最新消息、使用指南与轮班生活故事。', help:'探索 ShiftMate', tag:'你的班次，你的节奏。', notice:'公告', noticeDesc:'查看重要更新与公告。', guide:'使用指南', guideDesc:'了解各项功能的使用方法。', faq:'常见问题', faqDesc:'查找问题解答与解决方法。', story:'故事', storyDesc:'阅读此语言的博客文章。', soon:'即将推出', all:'显示全部', filter:'简体中文文章', search:'搜索', searchHint:'搜索博客', read:'继续阅读', updateBadge:'更新'},
    'zh-TW': {desc:'ShiftMate 最新消息、使用指南與輪班生活故事。', help:'探索 ShiftMate', tag:'你的班表，你的節奏。', notice:'公告', noticeDesc:'查看重要更新與公告。', guide:'使用指南', guideDesc:'了解各項功能的使用方法。', faq:'常見問題', faqDesc:'查找問題解答與解決方法。', story:'故事', storyDesc:'閱讀此語言的部落格文章。', soon:'即將推出', all:'顯示全部', filter:'繁體中文文章', search:'搜尋', searchHint:'搜尋部落格', read:'繼續閱讀', updateBadge:'更新'},
    ko: {desc:'ShiftMate 소식과 사용 가이드, 교대근무 이야기를 전합니다.', help:'ShiftMate 둘러보기', tag:'내 근무, 내 리듬대로', notice:'공지사항', noticeDesc:'중요한 업데이트와 안내를 확인하세요.', guide:'사용 가이드', guideDesc:'기능별 사용 방법을 확인하세요.', faq:'자주 묻는 질문', faqDesc:'궁금한 점과 해결 방법을 찾아보세요.', story:'스토리', storyDesc:'한국어 블로그 글을 모아보세요.', soon:'준비 중', all:'전체 글', filter:'한국어로 작성된 글', search:'검색', searchHint:'블로그에서 검색', read:'더 읽기', updateBadge:'업데이트'},
    ja: {desc:'ShiftMateのお知らせ、使い方、シフト勤務にまつわる読みもの。', help:'ShiftMateをもっと知る', tag:'シフトも、毎日も、自分のリズムで。', notice:'お知らせ', noticeDesc:'重要な更新情報とお知らせを確認できます。', guide:'使い方ガイド', guideDesc:'機能ごとの使い方を確認できます。', faq:'よくある質問', faqDesc:'疑問や困ったときの解決方法。', story:'ストーリー', storyDesc:'日本語の記事を読む。', soon:'準備中', all:'すべての記事', filter:'日本語の記事', search:'検索', searchHint:'ブログ内を検索', read:'続きを読む', updateBadge:'アップデート'},
    vi: {desc:'Tin tức, hướng dẫn và câu chuyện về cuộc sống làm ca với ShiftMate.', help:'Khám phá ShiftMate', tag:'Ca trực của bạn. Nhịp sống của bạn.', notice:'Thông báo', noticeDesc:'Xem cập nhật và thông báo quan trọng.', guide:'Hướng dẫn sử dụng', guideDesc:'Tìm hiểu cách dùng ShiftMate.', faq:'Câu hỏi thường gặp', faqDesc:'Tìm câu trả lời và cách khắc phục.', story:'Câu chuyện', storyDesc:'Đọc bài viết bằng ngôn ngữ này.', soon:'Sắp ra mắt', all:'Tất cả bài viết', filter:'Bài viết bằng tiếng Việt', search:'Tìm kiếm', searchHint:'Tìm kiếm trong blog', read:'Đọc thêm', updateBadge:'Cập nhật'}
  };


  var NOTICE_BADGE_TEXT = {
    en: {general:'Notice',update:'Update',maintenance:'Maintenance',incident:'Incident',feature:'Feature',service:'Service',policy:'Policy'},
    es: {general:'Aviso',update:'Actualización',maintenance:'Mantenimiento',incident:'Incidencia',feature:'Función',service:'Servicio',policy:'Política'},
    de: {general:'Mitteilung',update:'Update',maintenance:'Wartung',incident:'Störung',feature:'Funktion',service:'Service',policy:'Richtlinie'},
    fr: {general:'Annonce',update:'Mise à jour',maintenance:'Maintenance',incident:'Incident',feature:'Fonctionnalité',service:'Service',policy:'Politique'},
    'pt-BR': {general:'Aviso',update:'Atualização',maintenance:'Manutenção',incident:'Incidente',feature:'Recurso',service:'Serviço',policy:'Política'},
    'zh-CN': {general:'公告',update:'更新',maintenance:'维护',incident:'故障',feature:'新功能',service:'服务',policy:'政策'},
    'zh-TW': {general:'公告',update:'更新',maintenance:'維護',incident:'異常',feature:'新功能',service:'服務',policy:'政策'},
    ko: {general:'공지',update:'업데이트',maintenance:'점검',incident:'장애',feature:'기능 안내',service:'서비스 안내',policy:'정책 안내'},
    ja: {general:'お知らせ',update:'アップデート',maintenance:'メンテナンス',incident:'障害',feature:'機能案内',service:'サービス案内',policy:'ポリシー'},
    vi: {general:'Thông báo',update:'Cập nhật',maintenance:'Bảo trì',incident:'Sự cố',feature:'Tính năng',service:'Dịch vụ',policy:'Chính sách'}
  };

  var NOTICE_TYPE_ORDER = ['incident','maintenance','update','feature','service','policy','general'];

  function noticeBadgeText(id, type) {
    var table = NOTICE_BADGE_TEXT[id] || NOTICE_BADGE_TEXT.en;
    return table[type] || (NOTICE_BADGE_TEXT.en[type] || type);
  }

  var current = 'ko';
  function byClass(name) { return document.getElementsByClassName ? document.getElementsByClassName(name) : []; }
  function hasClass(el, c) { return (' ' + (el.className || '') + ' ').indexOf(' ' + c + ' ') > -1; }
  function setTextByClass(c, v) { var n=byClass(c); for (var i=0; i<n.length; i++) n[i].textContent = v; }
  function safeGet(k) { try { return localStorage.getItem(k); } catch(e) { return null; } }
  function safeSet(k, v) { try { localStorage.setItem(k, v); } catch(e) {} }
  function qs(key) { var m = location.search.match(new RegExp('[?&]' + key + '=([^&]+)')); return m ? decodeURIComponent(m[1].replace(/\+/g, ' ')) : ''; }

  function norm(v) {
    if (!v) return '';
    v = String(v).toLowerCase();
    if (v === 'ko' || v.indexOf('korean') > -1) return 'ko';
    if (v === 'ja' || v.indexOf('japanese') > -1) return 'ja';
    if (v === 'es' || v.indexOf('spanish') > -1) return 'es';
    if (v === 'de' || v.indexOf('german') > -1 || v.indexOf('deutsch') > -1) return 'de';
    if (v === 'fr' || v.indexOf('french') > -1 || v.indexOf('français') > -1 || v.indexOf('francais') > -1) return 'fr';
    if (v === 'pt' || v.indexOf('pt-br') > -1 || v.indexOf('portugu') > -1) return 'pt-BR';
    if (v === 'vi') return 'vi';
    if (v.indexOf('zh-tw') > -1 || v.indexOf('hant') > -1) return 'zh-TW';
    if (v.indexOf('zh') > -1 || v.indexOf('hans') > -1) return 'zh-CN';
    if (v === 'en' || v.indexOf('english') > -1) return 'en';
    return '';
  }

  function detect() {
    var href = decodeURIComponent(location.href).toLowerCase();
    /* FAQ/Guide Page paths are authoritative. Legacy sm-lang must not override the Page locale. */
    if (href.indexOf('faq-ko.html') > -1 || href.indexOf('guide-ko.html') > -1 || href.indexOf('lang-ko') > -1 || href.indexOf('한국어') > -1) return 'ko';
    if (href.indexOf('faq-ja.html') > -1 || href.indexOf('guide-ja.html') > -1 || href.indexOf('lang-ja') > -1) return 'ja';
    if (href.indexOf('faq-es.html') > -1 || href.indexOf('guide-es.html') > -1 || href.indexOf('lang-es') > -1) return 'es';
    if (href.indexOf('faq-de.html') > -1 || href.indexOf('guide-de.html') > -1 || href.indexOf('lang-de') > -1) return 'de';
    if (href.indexOf('faq-fr.html') > -1 || href.indexOf('guide-fr.html') > -1 || href.indexOf('lang-fr') > -1) return 'fr';
    if (href.indexOf('faq-pt-br.html') > -1 || href.indexOf('guide-pt-br.html') > -1 || href.indexOf('lang-pt-br') > -1) return 'pt-BR';
    if (href.indexOf('faq-vi.html') > -1 || href.indexOf('guide-vi.html') > -1 || href.indexOf('lang-vi') > -1) return 'vi';
    if (href.indexOf('faq-tw.html') > -1 || href.indexOf('guide-tw.html') > -1 || href.indexOf('lang-zh-tw') > -1) return 'zh-TW';
    if (href.indexOf('faq-cn.html') > -1 || href.indexOf('guide-cn.html') > -1 || href.indexOf('lang-zh-cn') > -1) return 'zh-CN';
    if (href.indexOf('/p/faq.html') > -1 || href.indexOf('/p/guide.html') > -1 || href.indexOf('/search/label/lang') > -1 || href.indexOf('lang-en') > -1) return 'en';
    var fromParam = norm(qs('sm-lang'));
    if (fromParam && LOCALES[fromParam]) return fromParam;
    var saved = norm(safeGet('shiftmate.blog.locale.v2'));
    if (saved && LOCALES[saved]) return saved;
    return 'en';
  }

  function url(id, kind) {
    var v = LOCALES[id] && LOCALES[id][kind];
    if (!v) return '';
    /* Keep Blogger Page URLs canonical. Locale state is stored locally, not in the URL. */
    return v;
  }

  function sectionKind() {
    var href = decodeURIComponent(location.href).toLowerCase();
    if (href.indexOf('/p/guide') > -1 || href.indexOf('+guide') > -1) return 'guide';
    if (href.indexOf('/p/faq') > -1) return 'faq';
    if (href.indexOf('+notice') > -1) return 'notice';
    if (href.indexOf('+story') > -1) return 'story';
    return 'blog';
  }

  function pagePath(id, kind) {
    var value = LOCALES[id] && LOCALES[id][kind];
    return value && value.indexOf('/p/') === 0 ? value : '';
  }

  function absolutePageUrl(path) {
    return location.protocol + '//' + location.host + path;
  }

  function cleanLegacyPageUrl() {
    var kind = sectionKind();
    var search = location.search || '';
    if ((kind !== 'faq' && kind !== 'guide') || search.toLowerCase().indexOf('sm-lang=') === -1) return;
    if (!window.history || !window.history.replaceState) return;

    var parts = search.replace(/^\?/, '').split('&');
    var kept = [];
    for (var i=0; i<parts.length; i++) {
      if (parts[i] && !/^sm-lang=/i.test(parts[i])) kept.push(parts[i]);
    }
    var next = location.pathname + (kept.length ? '?' + kept.join('&') : '') + (location.hash || '');
    window.history.replaceState(null, document.title, next);
  }

  function syncPageSeo(id) {
    var kind = sectionKind();
    if (kind !== 'faq' && kind !== 'guide') return;

    var path = pagePath(id, kind);
    if (!path) return;

    var canonical = document.querySelector ? document.querySelector('link[rel="canonical"]') : null;
    if (!canonical && document.head) {
      canonical = document.createElement('link');
      canonical.setAttribute('rel', 'canonical');
      document.head.appendChild(canonical);
    }
    if (canonical) canonical.setAttribute('href', absolutePageUrl(path));

    if (!document.querySelectorAll || !document.head) return;
    var old = document.querySelectorAll('link[data-shiftmate-seo="alternate"]');
    for (var oi=old.length-1; oi>=0; oi--) {
      if (old[oi].parentNode) old[oi].parentNode.removeChild(old[oi]);
    }

    for (var j=0; j<ORDER.length; j++) {
      var locale = ORDER[j];
      var alternatePath = pagePath(locale, kind);
      if (!alternatePath) continue;
      var alternate = document.createElement('link');
      alternate.setAttribute('rel', 'alternate');
      alternate.setAttribute('hreflang', LOCALES[locale].tag);
      alternate.setAttribute('href', absolutePageUrl(alternatePath));
      alternate.setAttribute('data-shiftmate-seo', 'alternate');
      document.head.appendChild(alternate);
    }

    var defaultPath = pagePath('en', kind);
    if (defaultPath) {
      var xDefault = document.createElement('link');
      xDefault.setAttribute('rel', 'alternate');
      xDefault.setAttribute('hreflang', 'x-default');
      xDefault.setAttribute('href', absolutePageUrl(defaultPath));
      xDefault.setAttribute('data-shiftmate-seo', 'alternate');
      document.head.appendChild(xDefault);
    }
  }

  function ensureRuntimeStyles() {
    if (!document.head || document.getElementById('shiftmate-runtime-styles')) return;
    var style=document.createElement('style');
    style.id='shiftmate-runtime-styles';
    style.textContent=
      '.sm-notice-page .blog-posts .post-outer-container{box-sizing:border-box;margin:0 0 18px!important;padding:22px!important;border:1px solid #e1e3e9!important;border-radius:16px;background:#fff;box-shadow:0 6px 20px rgba(20,21,45,.05);transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease;}' +
      '.sm-notice-page .blog-posts .post-outer-container+.post-outer-container{padding-top:22px!important;border-top:1px solid #e1e3e9!important;}' +
      '.sm-notice-page .blog-posts .post-outer-container:hover{transform:translateY(-2px);box-shadow:0 10px 26px rgba(20,21,45,.08);border-color:#cfd2dc!important;}' +
      '.sm-notice-page .blog-posts .post-outer{margin:0!important;}' +
      '.sm-notice-page .blog-posts .date-header{display:none!important;}' +
      '.sm-notice-page .blog-posts .post-title,.sm-notice-page .blog-posts .entry-title{margin:4px 0 10px!important;font-size:1.28rem!important;line-height:1.45!important;color:#14152d!important;}' +
      '.sm-notice-page .blog-posts .post-title a,.sm-notice-page .blog-posts .entry-title a{color:inherit!important;text-decoration:none!important;}' +
      '.sm-notice-page .blog-posts .post-header{margin:0 0 12px!important;color:#717684!important;font-size:.84rem!important;}' +
      '.sm-notice-page .blog-posts .post-body{color:#4a4f5d!important;line-height:1.75!important;}' +
      '.sm-notice-page .blog-posts .jump-link{margin-top:14px!important;}' +
      '.sm-notice-page .blog-posts .jump-link>a{display:inline-flex!important;align-items:center;min-height:38px;padding:7px 13px;border:1px solid #d8dbe4;border-radius:999px;background:#f7f8fa;color:#14152d!important;text-decoration:none!important;font-weight:600;font-size:.9rem;}' +
      '.sm-notice-badges{display:flex;flex-wrap:wrap;gap:7px;margin:0 0 10px;}' +
      '.sm-notice-badge{display:inline-flex;align-items:center;min-height:26px;padding:3px 9px;border-radius:999px;background:#f1f2f6;color:#3e4351;font-size:.76rem;font-weight:700;line-height:1.2;border:1px solid transparent;}' +
      '.sm-notice-badge-type-general{background:#f1f2f6;color:#3e4351;}' +
      '.sm-notice-badge-type-update{background:#eef0f8;color:#14152d;border-color:#d9dcea;}' +
      '.sm-notice-badge-type-maintenance{background:#fff7e8;color:#77510a;border-color:#f0dfbd;}' +
      '.sm-notice-badge-type-incident{background:#fff0ef;color:#9d211d;border-color:#f2cfcc;}' +
      '.sm-notice-badge-type-feature{background:#edf7f2;color:#245f49;border-color:#d0e8dc;}' +
      '.sm-notice-badge-type-service{background:#f5f0fa;color:#5e3d7b;border-color:#e3d6ef;}' +
      '.sm-notice-badge-type-policy{background:#f3f4f6;color:#414651;border-color:#dfe2e7;}' +
      '.sm-notice-badge-version{background:#14152d;color:#fff;}' +
      '.sm-release-detail-state{box-sizing:border-box;max-width:760px;margin:28px auto;padding:28px 24px;border:1px solid #e1e3e9;border-radius:18px;background:#fff;box-shadow:0 8px 26px rgba(20,21,45,.06);text-align:left;}' +
      '.sm-release-detail-state h2{margin:0 0 10px;color:#14152d;font-size:1.35rem;line-height:1.4;}' +
      '.sm-release-detail-state p{margin:0;color:#565b68;line-height:1.7;}' +
      '.sm-release-detail-version{display:inline-flex;margin-bottom:12px;padding:4px 9px;border-radius:999px;background:#14152d;color:#fff;font-size:.78rem;font-weight:700;}' +
      '@media(max-width:600px){.sm-notice-page .blog-posts .post-outer-container{padding:17px!important;border-radius:14px;}.sm-notice-page .blog-posts .post-outer-container+.post-outer-container{padding-top:17px!important;}.sm-notice-page .blog-posts .post-title,.sm-notice-page .blog-posts .entry-title{font-size:1.12rem!important;}}';
    document.head.appendChild(style);
  }

  function setMeta(selector, attr, value, content) {
    if (!document.head || !document.querySelector) return;
    var meta=document.querySelector(selector);
    if (!meta) {
      meta=document.createElement('meta');
      meta.setAttribute(attr,value);
      meta.setAttribute('data-shiftmate-seo','post');
      document.head.appendChild(meta);
    }
    meta.setAttribute('content',content);
  }

  function ensureCanonical(href) {
    if (!document.head || !document.querySelector) return href;
    var canonical=document.querySelector('link[rel="canonical"]');
    if (!canonical) {
      canonical=document.createElement('link');
      canonical.setAttribute('rel','canonical');
      canonical.setAttribute('data-shiftmate-seo','post');
      document.head.appendChild(canonical);
    }
    var current=canonical.getAttribute('href') || href;
    canonical.setAttribute('href',current);
    return current;
  }

  function syncPostSeo() {
    if (!document.querySelectorAll || !document.head) return;
    var posts=document.querySelectorAll('article.sm-post');
    var marker=document.querySelector('.sm-post-seo[data-sm-description]');
    if (posts.length !== 1 || !marker) return;

    var description=(marker.getAttribute('data-sm-description') || '').replace(/\s+/g,' ').trim();
    if (!description) return;

    var titleNode=document.querySelector('.Blog .post-title,.Blog .entry-title');
    var title=titleNode ? (titleNode.textContent || '').replace(/\s+/g,' ').trim() : document.title;
    var cleanUrl=location.protocol + '//' + location.host + location.pathname;
    var canonical=ensureCanonical(cleanUrl);
    var published=document.querySelector('time.published[datetime],.post-timestamp time[datetime]');
    var publishedTime=published ? (published.getAttribute('datetime') || '') : '';

    setMeta('meta[name="description"]','name','description',description);
    setMeta('meta[property="og:description"]','property','og:description',description);
    setMeta('meta[name="twitter:description"]','name','twitter:description',description);
    if (title) {
      setMeta('meta[property="og:title"]','property','og:title',title);
      setMeta('meta[name="twitter:title"]','name','twitter:title',title);
    }
    setMeta('meta[property="og:type"]','property','og:type','article');
    setMeta('meta[property="og:url"]','property','og:url',canonical);
    setMeta('meta[property="og:site_name"]','property','og:site_name','ShiftMate');
    setMeta('meta[name="twitter:card"]','name','twitter:card','summary');
    if (publishedTime) {
      setMeta('meta[property="article:published_time"]','property','article:published_time',publishedTime);
    }
  }
  function syncPostSeo() {
    if (!document.querySelectorAll) return;
    var posts=document.querySelectorAll('article.sm-post');
    var marker=document.querySelector('.sm-post-seo[data-sm-description]');
    if (posts.length !== 1 || !marker) return;
    var description=marker.getAttribute('data-sm-description') || '';
    description=description.replace(/\s+/g,' ').trim();
    if (!description) return;
    setMeta('meta[name="description"]','name','description',description);
    setMeta('meta[property="og:description"]','property','og:description',description);
    setMeta('meta[name="twitter:description"]','name','twitter:description',description);
  }

  function labelFromHref(href) {
    try {
      var decoded=decodeURIComponent(href || '');
      var marker='/search/label/';
      var at=decoded.indexOf(marker);
      if (at < 0) return '';
      return decoded.slice(at + marker.length).split(/[?#]/)[0];
    } catch(e) { return ''; }
  }

  var RELEASE_DETAIL_TEXT = {
    en: {title:'Update details are being prepared', body:'Detailed information for this ShiftMate update will be available here when it is published.', error:'We couldn’t open the update details. Please try again later.'},
    ko: {title:'업데이트 상세 안내를 준비하고 있습니다', body:'ShiftMate 업데이트의 자세한 내용은 게시되는 즉시 이 페이지에서 확인할 수 있습니다.', error:'업데이트 상세 안내를 열지 못했습니다. 잠시 후 다시 시도해 주세요.'},
    ja: {title:'アップデートの詳細を準備しています', body:'ShiftMate アップデートの詳細は、公開後すぐにこのページから確認できます。', error:'アップデートの詳細を開けませんでした。しばらくしてからもう一度お試しください。'},
    'zh-CN': {title:'更新详情正在准备中', body:'ShiftMate 更新的详细内容发布后即可在此页面查看。', error:'无法打开更新详情，请稍后重试。'},
    'zh-TW': {title:'更新詳細資訊準備中', body:'ShiftMate 更新的詳細內容發布後即可在此頁面查看。', error:'無法開啟更新詳細資訊，請稍後再試。'},
    es: {title:'Estamos preparando los detalles de la actualización', body:'Los detalles de esta actualización de ShiftMate estarán disponibles aquí en cuanto se publiquen.', error:'No se pudieron abrir los detalles de la actualización. Inténtalo de nuevo más tarde.'},
    vi: {title:'Đang chuẩn bị thông tin chi tiết về bản cập nhật', body:'Thông tin chi tiết về bản cập nhật ShiftMate sẽ có tại đây ngay khi được đăng.', error:'Không thể mở thông tin chi tiết về bản cập nhật. Vui lòng thử lại sau.'},
    de: {title:'Update-Details werden vorbereitet', body:'Die Details zu diesem ShiftMate-Update sind hier verfügbar, sobald sie veröffentlicht wurden.', error:'Die Update-Details konnten nicht geöffnet werden. Bitte versuche es später erneut.'},
    'pt-BR': {title:'Estamos preparando os detalhes da atualização', body:'Os detalhes desta atualização do ShiftMate estarão disponíveis aqui assim que forem publicados.', error:'Não foi possível abrir os detalhes da atualização. Tente novamente mais tarde.'},
    fr: {title:'Les détails de la mise à jour sont en préparation', body:'Les détails de cette mise à jour de ShiftMate seront disponibles ici dès leur publication.', error:'Impossible d’ouvrir les détails de la mise à jour. Réessayez plus tard.'}
  };

  function routeReleaseDetail(id) {
    if (sectionKind() !== 'notice' || qs('sm-detail') !== '1' || !document.querySelectorAll) return false;

    var version=(qs('sm-version') || '').trim();
    var posts=document.querySelectorAll('.blog-posts .post-outer-container');
    var matches=[];

    if (version) {
      for (var i=0;i<posts.length;i++) {
        var labels=posts[i].querySelectorAll('.sm-post-language-data [data-sm-post-label]');
        for (var j=0;j<labels.length;j++) {
          if ((labels[j].getAttribute('data-sm-post-label') || '').trim() === version) {
            matches.push(posts[i]);
            break;
          }
        }
      }
    }

    if (matches.length === 1) {
      var link=matches[0].querySelector('.post-title a,.entry-title a');
      var href=link && link.getAttribute('href');
      if (href) {
        window.location.replace(href);
        return true;
      }
    }

    var blogPosts=document.querySelector('.blog-posts');
    var host=blogPosts
      ? blogPosts.parentNode
      : (document.querySelector('.main-inner,.content-inner,main,#main') || document.body);
    if (!host) return true;
    if (blogPosts) blogPosts.style.display='none';

    var emptyMessage=document.querySelector('.post-filter-message,.status-msg-wrap');
    if (emptyMessage) emptyMessage.style.display='none';

    var panel=document.getElementById('sm-release-detail-state');
    if (!panel) {
      var copy=RELEASE_DETAIL_TEXT[id] || RELEASE_DETAIL_TEXT.en;
      panel=document.createElement('section');
      panel.id='sm-release-detail-state';
      panel.className='sm-release-detail-state';
      panel.setAttribute('role','status');

      if (version) {
        var versionBadge=document.createElement('div');
        versionBadge.className='sm-release-detail-version';
        versionBadge.textContent='ShiftMate ' + version;
        panel.appendChild(versionBadge);
      }

      var heading=document.createElement('h2');
      heading.textContent=matches.length > 1 ? copy.error : copy.title;
      panel.appendChild(heading);

      var body=document.createElement('p');
      body.textContent=matches.length > 1 ? copy.error : copy.body;
      panel.appendChild(body);

      host.insertBefore(panel,blogPosts || host.firstChild);
    }
    return true;
  }

  function enhanceNoticeListing(id) {
    var root=document.documentElement, isNotice=sectionKind()==='notice';
    if (isNotice) root.className=(root.className || '').replace(/\bsm-notice-page\b/g,'').trim() + ' sm-notice-page';
    else root.className=(root.className || '').replace(/\bsm-notice-page\b/g,'').replace(/\s+/g,' ').trim();
    if (!isNotice || !document.querySelectorAll) return;

    var posts=document.querySelectorAll('.blog-posts .post-outer-container');
    for (var i=0;i<posts.length;i++) {
      var post=posts[i];
      if (post.getAttribute('data-sm-notice-enhanced')==='1') continue;

      var labelNodes=post.querySelectorAll('.sm-post-language-data [data-sm-post-label]');
      var version='', type='', found={};
      for (var j=0;j<labelNodes.length;j++) {
        var name=(labelNodes[j].getAttribute('data-sm-post-label') || '').trim();
        var lower=name.toLowerCase();
        if (/^\d+\.\d+\.\d+(?:[-+][A-Za-z0-9.-]+)?$/.test(name)) version=name;
        if (lower) found[lower]=true;
      }

      for (var ti=0;ti<NOTICE_TYPE_ORDER.length;ti++) {
        if (found[NOTICE_TYPE_ORDER[ti]]) {
          type=NOTICE_TYPE_ORDER[ti];
          break;
        }
      }

      if (version || type) {
        var badges=document.createElement('div');
        badges.className='sm-notice-badges';

        if (type) {
          var typeBadge=document.createElement('span');
          typeBadge.className='sm-notice-badge sm-notice-badge-type-' + type;
          typeBadge.textContent=noticeBadgeText(id,type);
          badges.appendChild(typeBadge);
        }

        if (version) {
          var v=document.createElement('span');
          v.className='sm-notice-badge sm-notice-badge-version';
          v.textContent='v' + version;
          badges.appendChild(v);
        }

        var titleContainer=post.querySelector('.post-title-container');
        var title=post.querySelector('.post-title,.entry-title');
        if (titleContainer) titleContainer.insertBefore(badges,titleContainer.firstChild);
        else if (title && title.parentNode) title.parentNode.insertBefore(badges,title);
        else post.insertBefore(badges,post.firstChild);
      }

      post.setAttribute('data-sm-notice-enhanced','1');
    }
  }
  function menuHtml(id, compact) {
    var t = TEXT[id] || TEXT.en;
    var rows = [['notice',t.notice,t.noticeDesc],['guide',t.guide,t.guideDesc],['faq',t.faq,t.faqDesc],['story',t.story,t.storyDesc]];
    var h='';
    if (!compact) h += '<div class="sm-support-heading"><h2>' + t.help + '</h2><span class="sm-locale-chip">' + LOCALES[id].name + '</span></div>';
    h += '<nav class="' + (compact ? 'sm-quick-menu' : 'sm-menu') + '" aria-label="' + t.help + '">';
    for (var i=0; i<rows.length; i++) {
      var k=rows[i][0], href=url(id,k), unavailable=!href, tag=unavailable?'span':'a';
      h += '<' + tag + ' class="sm-menu-item' + (unavailable?' sm-unavailable':'') + '"';
      if (!unavailable) h += ' href="' + href + '" data-sm-menu="' + k + '" data-sm-locale-link="' + id + '"' + (sectionKind()===k?' aria-current="page"':'');
      h += '><span class="sm-menu-icon">•</span><span class="sm-menu-copy"><span class="sm-menu-title">' + rows[i][1] + '</span>';
      if (unavailable) h += '<span class="sm-menu-pending">' + t.soon + '</span>';
      else if (!compact) h += '<span class="sm-menu-description">' + rows[i][2] + '</span>';
      h += '</span>'; if (!compact && !unavailable) h += '<span class="sm-menu-arrow">›</span>'; h += '</' + tag + '>';
    }
    h += '</nav>';
    if (!compact) {
      h += '<details class="sm-other-languages"><summary>' + (id==='ko'?'다른 언어의 FAQ':'FAQ languages') + '</summary><div class="sm-faq-language-links">';
      for (var j=0; j<ORDER.length; j++) { var other=ORDER[j]; if (other!==id) h += '<a href="' + url(other,'faq') + '" lang="' + LOCALES[other].tag + '">' + LOCALES[other].name + '</a>'; }
      h += '</div></details>';
    }
    return h;
  }

  function languageNavHtml(id) {
    var h='<ul class="sm-language-list">', kind=sectionKind();
    for (var i=0; i<ORDER.length; i++) {
      var k=ORDER[i], l=LOCALES[k], selected=k===id, href=url(k,kind)||l.blog;
      h += '<li' + (selected?' class="selected"':'') + '><a class="sm-language-link" href="' + href + '" lang="' + l.tag + '" hreflang="' + l.tag + '" data-sm-locale-link="' + k + '"' + (selected?' aria-current="true"':'') + '>' + l.name + '</a></li>';
    }
    return h + '</ul>';
  }

  function updateFilter(id) {
    var t=TEXT[id]||TEXT.en, descs=byClass('post-filter-description');
    for (var i=0; i<descs.length; i++) descs[i].textContent=t.filter;
    var links=document.querySelectorAll?document.querySelectorAll('.post-filter-message a'):[];
    for (var j=0; j<links.length; j++) links[j].textContent=t.all;
  }

  function render(id) {
    if (!LOCALES[id]) id=detect();
    current=id; safeSet('shiftmate.blog.locale.v2',id);
    document.documentElement.setAttribute('data-sm-locale',id);
    document.documentElement.setAttribute('lang',LOCALES[id].tag);
    ensureRuntimeStyles();
    if (routeReleaseDetail(id)) return;
    syncPageSeo(id);
    syncPostSeo();
    enhanceNoticeListing(id);
    var t=TEXT[id]||TEXT.en;
    setTextByClass('sm-header-description',t.desc);
    setTextByClass('sm-sidebar-tagline',t.tag);
    setTextByClass('search-expand-text',t.search);
    var q=document.querySelectorAll?document.querySelectorAll('#search_top input[name="q"]'):[];
    for (var qi=0; qi<q.length; qi++) { q[qi].placeholder=t.searchHint; q[qi].setAttribute('aria-label',t.searchHint); }
    var navs=byClass('sm-language-nav'); for (var n=0; n<navs.length; n++) navs[n].innerHTML=languageNavHtml(id);
    var mounts=byClass('sm-js-support'); for (var m=0; m<mounts.length; m++) mounts[m].innerHTML=menuHtml(id,hasClass(mounts[m],'sm-js-support-compact'));
    updateFilter(id);
    var reads=document.querySelectorAll?document.querySelectorAll('.jump-link > a'):[];
    for (var r=0; r<reads.length; r++) reads[r].textContent=t.read;
  }

  function clickHandler(e) {
    e=e||window.event; var a=e.target||e.srcElement;
    while (a && a.tagName!=='A') a=a.parentNode;
    if (!a) return;
    var id=a.getAttribute('data-sm-locale-link');
    if (id && LOCALES[id]) { safeSet('shiftmate.blog.locale.v2',id); render(id); }
  }

  function boot() { cleanLegacyPageUrl(); render(detect()); }
  if (document.addEventListener) document.addEventListener('click',clickHandler,true);
  else if (document.attachEvent) document.attachEvent('onclick',clickHandler);
  boot(); setTimeout(boot,50); setTimeout(boot,250); setTimeout(boot,1000); setTimeout(boot,2500);
  if (window.addEventListener) window.addEventListener('load',boot,false);
  window.ShiftMateBlog={refresh:boot,getLanguage:function(){return current;}};
}());

(function () {
  'use strict';

  function normalize(value) {
    return (value || '')
      .toLocaleLowerCase()
      .replace(/\s+/g, ' ')
      .trim();
  }

  function openHashTarget(guide) {
    if (!window.location.hash) return;

    var id = decodeURIComponent(window.location.hash.substring(1));
    var target = document.getElementById(id);
    if (!target || !guide.contains(target)) return;

    if (target.tagName && target.tagName.toLowerCase() === 'details') {
      target.open = true;
    }

    var parentDetails = target.closest ? target.closest('details') : null;
    if (parentDetails) parentDetails.open = true;

    window.setTimeout(function () {
      target.scrollIntoView({behavior: 'smooth', block: 'start'});
    }, 70);
  }

  function initSearch(guide) {
    var form = guide.querySelector('[data-guide-search]');
    if (!form) return;

    var input = form.querySelector('input');
    var empty = guide.querySelector('.sm-guide-search-empty');
    var sections = Array.prototype.slice.call(
      guide.querySelectorAll('.sm-guide-section')
    );

    function reset() {
      sections.forEach(function (section) {
        section.hidden = false;
        Array.prototype.forEach.call(
          section.querySelectorAll('.sm-guide-item'),
          function (item) {
            item.hidden = false;
          }
        );
      });
      if (empty) empty.classList.remove('is-visible');
    }

    function run() {
      var query = normalize(input.value);
      if (!query) {
        reset();
        return;
      }

      var total = 0;

      sections.forEach(function (section) {
        var heading = section.querySelector('h2');
        var sectionTitleMatch =
          normalize(heading ? heading.textContent : '').indexOf(query) !== -1;

        var items = Array.prototype.slice.call(
          section.querySelectorAll('.sm-guide-item')
        );

        if (!items.length) {
          var simpleMatch =
            normalize(section.textContent).indexOf(query) !== -1;
          section.hidden = !simpleMatch;
          if (simpleMatch) total += 1;
          return;
        }

        var matched = 0;

        items.forEach(function (item) {
          var searchText =
            (item.getAttribute('data-search') || '') + ' ' +
            (item.textContent || '');

          var isMatch =
            sectionTitleMatch ||
            normalize(searchText).indexOf(query) !== -1;

          item.hidden = !isMatch;

          if (isMatch) {
            item.open = true;
            matched += 1;
            total += 1;
          }
        });

        section.hidden = matched === 0;
      });

      if (empty) {
        empty.classList.toggle('is-visible', total === 0);
      }
    }

    form.addEventListener('submit', function (event) {
      event.preventDefault();
      run();
    });

    input.addEventListener('input', run);
    input.addEventListener('search', function () {
      if (!input.value) reset();
    });
  }

  function initVideos(guide) {
    var buttons = guide.querySelectorAll('.sm-guide-video[data-video-id]');

    Array.prototype.forEach.call(buttons, function (button) {
      var videoId = (button.getAttribute('data-video-id') || '').trim();
      if (!videoId || !/^[A-Za-z0-9_-]{6,20}$/.test(videoId)) return;

      var image = button.querySelector('img');
      if (image && !image.getAttribute('src')) {
        image.setAttribute(
          'src',
          'https://i.ytimg.com/vi/' + videoId + '/hqdefault.jpg'
        );
      }

      button.addEventListener('click', function () {
        var wrapper = document.createElement('div');
        wrapper.className = 'sm-guide-video-frame';

        var iframe = document.createElement('iframe');
        iframe.src =
          'https://www.youtube-nocookie.com/embed/' +
          videoId +
          '?autoplay=1&rel=0';
        iframe.title =
          button.getAttribute('data-title') || 'ShiftMate guide video';
        iframe.loading = 'lazy';
        iframe.allow =
          'accelerometer; autoplay; clipboard-write; encrypted-media; ' +
          'gyroscope; picture-in-picture; web-share';
        iframe.allowFullscreen = true;

        wrapper.appendChild(iframe);
        button.replaceWith(wrapper);
      }, {once: true});
    });
  }

  function initToc(guide) {
    if (!('IntersectionObserver' in window)) return;

    var links = Array.prototype.slice.call(
      guide.querySelectorAll('.sm-guide-toc a[href^="#"]')
    );
    var sections = Array.prototype.slice.call(
      guide.querySelectorAll('.sm-guide-section[id]')
    );
    if (!links.length || !sections.length) return;

    var byId = {};
    links.forEach(function (link) {
      byId[link.getAttribute('href').substring(1)] = link;
    });

    var observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;

        links.forEach(function (link) {
          link.removeAttribute('aria-current');
        });

        if (byId[entry.target.id]) {
          byId[entry.target.id].setAttribute('aria-current', 'location');
        }
      });
    }, {rootMargin: '-18% 0px -68% 0px', threshold: 0});

    sections.forEach(function (section) {
      observer.observe(section);
    });
  }

  function init() {
    var guide = document.querySelector('[data-shiftmate-guide]');
    if (!guide) return;

    document.body.classList.add('sm-guide-page');
    initSearch(guide);
    initVideos(guide);
    initToc(guide);
    openHashTarget(guide);

    window.addEventListener('hashchange', function () {
      openHashTarget(guide);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
}());
